205	
206	                        if (!$allPending) {
207	
208	                            // disable "save" button
209	                            $form->disabled();
210	
211	                            return [
212	                                Placeholder::make('status')
213	                                    ->label('')
214	                                    ->content('Tutti i record selezionati devono essere  "In attesa".'),
215	                            ];
216	                        }
217	
218	                        return [
219	                            ToggleButtons::make('status')
220	                                ->label('Nuovo stato')
221	                                // ->helperText('Solo i record con stato "In attesa" saranno aggiornati.')
222	                                ->options(
223	                                    collect(AwardRedeemStatus::cases())
224	                                        ->filter(fn ($status) => $status !== AwardRedeemStatus::PENDING)
225	                                        ->mapWithKeys(fn ($status) => [$status->value => $status->getLabel()])
226	                                )
227	                                ->inline()
228	                                ->required(),
229	                        ];
230	
231	
232	                    })
233	                    ->modalSubmitAction(function ($livewire, $action) {
234	                        $allPending = $livewire->getSelectedTableRecords()
235	                            ->every(fn ($record) => $record->status === AwardRedeemStatus::PENDING);
236	
237	                        return $allPending ? $action : false;
238	                    })
