16	
17	
18	    /**
19	     * Casts
20	     */
21	    protected $casts = [
22	        'status' => AwardRedeemStatus::class,
23	        'requested_at' => 'datetime',
24	        'approved_at' => 'datetime',
25	        'rejected_at' => 'datetime',
26	    ];
27	
28	    /**
29	     * Fillable fields
30	     */
31	    protected $fillable = [
32	        'user_id',
33	        'award_id',
34	        'uuid',
35	        'status',
36	        'requested_at',
37	        'approved_at',
38	        'user_firstname',
39	        'user_lastname',
40	        'user_address',
