51	        'rejected_at',
52	    ];
53	
54	    /**
55	     * On creation, retrieve data from related user
56	     */
57	    protected static function booted()
58	    {
59	        static::creating(function ($awardRedeem) {
60	
61	            // assign status
62	            if (!$awardRedeem->status) {
63	                $awardRedeem->status = AwardRedeemStatus::PENDING;
64	            }
65	
66	            // assign date
67	            if (!$awardRedeem->requested_at) {
68	                $awardRedeem->requested_at = now();
69	            }
70	        });
71	    }
72	
73	    /**
74	     * The award that is redeemed
75	     * @return BelongsTo<Award,$this>
76	     */
77	    public function award(): BelongsTo
78	    {
79	        return $this->belongsTo(Award::class);
80	    }
81	
82	
83	    /**
84	     * User that redeemed the award
85	     * @return BelongsTo<User,$this>
86	     */
87	    public function user(): BelongsTo
88	    {
89	        return $this->belongsTo(User::class);
90	    }
91	
92	
93	    /**
94	     * Scope a query to only include awards redeemed by a specific user.
95	     * @param Builder<AwardRedeem> $query
96	     */
97	    public function scopeByUser(Builder $query, User $user): void
98	    {
99	        $query->where('user_id', $user->id);
100	    }
101	
102	    /**
103	     * Scope a query to only include awards redeemed by a specific award.
104	     * @param Builder<AwardRedeem> $query
105	     */
106	    public function scopeByAward(Builder $query, Award $award): void
107	    {
108	        $query->where('award_id', $award->id);
109	    }
110	
111	}
