docker exec latavoladinonnonanni_web php artisan tinker --execute="
\$f = (new ReflectionClass(App\Filament\Resources\AwardRedeemResource::class));
\$filter = Filament\Tables\Filters\SelectFilter::make('status')->label('Stato')->options(App\Enums\AwardRedeemStatus::class)->multiple();
echo 'opzioni filtro: '.json_encode(\$filter->getOptions(), JSON_UNESCAPED_UNICODE).PHP_EOL;
echo '--- conteggi per stato ---'.PHP_EOL;
foreach(DB::table('award_redeems')->select('status', DB::raw('count(*) as c'))->groupBy('status')->get() as \$r){ echo \$r->status.': '.\$r->c.PHP_EOL; }
foreach(DB::select(\"EXPLAIN SELECT * FROM award_redeems WHERE status IN ('pending') ORDER BY created_at DESC LIMIT 50\") as \$e){ echo 'key: '.(\$e->key ?? 'NULL').' | rows: '.\$e->rows.PHP_EOL; }
" 2>&1 | tail -10

