49	    {
50	        $aggregateRoot = AwardRedeemAggregateRoot::retrieve($record->uuid);
51	
52	        /**
53	         * Update status only if it is "pending"
54	         */
55	        if ($record->status == AwardRedeemStatus::PENDING) {
56	            switch ($newStatus) {
57	                case AwardRedeemStatus::APPROVED->value:
58	                    $aggregateRoot->approve(Auth::user()->id)->persist();
